/// What an event says, by type.
public enum AgentEventPayload: Hashable, Sendable {
    /// A session began. The first event of every transcript.
    case sessionCreated(SessionCreated)
    /// What the next turn runs with. Only the fields that are set changed.
    case sessionConfigured(SessionConfigured)
    /// The session's state changed.
    case sessionState(SessionState)
    /// A turn began. Carries the turnId every event of the turn may name.
    case turnStarted(TurnStarted)
    /// A turn ended normally.
    case turnCompleted(TurnCompleted)
    /// A turn ended because something went wrong.
    case turnFailed(TurnFailed)
    /// A turn ended without finishing and without failing: a stop, a quit, a lost host. Any tool call still running has an unknown outcome.
    case turnInterrupted(TurnInterrupted)
    /// The transcript was rewound. A reader drops every turn and item it holds and rebuilds from the events that follow.
    case transcriptRestarted(TranscriptRestarted)
    /// A message from the reader.
    case itemUserMessage(ItemUserMessage)
    /// More of the agent's reply. Appended to the item's text.
    case itemAssistantTextDelta(ItemAssistantTextDelta)
    /// The whole of one reply. Replaces whatever the deltas built.
    case itemAssistantText(ItemAssistantText)
    /// More of the model's visible thinking. Appended to the item's text.
    case itemThinkingDelta(ItemThinkingDelta)
    /// A summary of the model's thinking. Replaces whatever the deltas built. Never raw private chain of thought.
    case itemThinking(ItemThinking)
    /// The agent called a tool. The call is running until its tool_result arrives.
    case itemToolCall(ItemToolCall)
    /// A chunk of a running call's live output.
    case itemToolOutput(ItemToolOutput)
    /// How a tool call ended.
    case itemToolResult(ItemToolResult)
    /// A file changed.
    case itemFileChange(ItemFileChange)
    /// A test run finished.
    case itemTestRun(ItemTestRun)
    /// A delegated agent's state, sent whenever it changes. The latest one wins.
    case itemSubagent(ItemSubagent)
    /// Older turns now reach the model as a summary. The transcript keeps them; only what the model is sent shrank.
    case itemCompaction(ItemCompaction)
    /// A quiet line the reader is owed: a hook stepped in, a setup step ran, the context was folded.
    case itemNotice(ItemNotice)
    /// The agent is waiting for a yes or a no.
    case approvalRequested(ApprovalRequested)
    /// An approval was answered.
    case approvalResolved(ApprovalResolved)
    /// The agent asked the reader something and is waiting.
    case questionAsked(QuestionAsked)
    /// A question was answered.
    case questionAnswered(QuestionAnswered)
    /// The whole todo list, as it now stands. Each snapshot replaces the last.
    case planUpdated(PlanUpdated)
    /// In plan mode, the agent proposes what it would do and waits for a decision before changing anything.
    case planProposed(PlanProposed)
    /// A proposed plan was approved or rejected.
    case planResolved(PlanResolved)
    /// Model usage incurred since the producer's previous usage report. Readers add them up.
    case usageUpdated(UsageUpdated)
    /// Something went wrong that the reader should see. Whether the turn goes on is said by the turn events, not here.
    case sessionError(SessionError)
    /// The runtime kept the run going with no new reader message: the stop check sent the agent back, or the reader resumed. A quiet caption, never the reader's words.
    case runContinued(RunContinued)
    /// How a run ended, with the report the runtime built from its recorded evidence.
    case runOutcome(RunOutcome)
    /// A check ran and its result counts as evidence. Recorded by the runtime, never claimed by the model.
    case verifyResult(VerifyResult)
    /// The running result was looked at: a preview route, a Simulator screen, a Mac app.
    case verifyUi(VerifyUi)
    /// A self-review of the diff finished.
    case reviewFindings(ReviewFindings)
    /// A goal was set. Setting one never changes the permission mode.
    case goalSet(GoalSet)
    /// A goal's objective, criteria, constraints or budget changed. Only the fields that are set changed.
    case goalUpdated(GoalUpdated)
    /// A goal was checked: the deterministic part, then the judge. The judge can only say keep working, met or impossible; it never allows anything.
    case goalVerdict(GoalVerdict)
    /// A goal's status or spend changed.
    case goalStatus(GoalStatus)
    /// Background work kept the run waiting long enough that the agent is asked to read it, keep waiting, or stop what is stuck.
    case checkinDue(CheckinDue)
    /// CI for a pull request the agent opened moved.
    case ciStatus(CiStatus)
    /// A run or goal budget was reached. A wrap-up turn follows; reaching a budget is never done, and Keep going adds the same budget again.
