/// Every event carries these keys, beside its own.
public struct AgentEvent: Hashable, Sendable, Codable, Identifiable {
    /// The protocol version the producer wrote, "<major>.<minor>". A reader refuses a major it does not know.
    public var v: String
    /// Unique per event and stable across retries: readers drop an id they have already applied.
    public var id: String
    /// The session this event belongs to.
    public var sessionId: String
    /// 1-based and increasing within one producer's stream of a session. Order, not identity; the id is the identity.
    public var seq: Int
    /// When it happened, at the producer.
    public var at: String
    /// The turn it belongs to. Absent means the turn that is open, if any.
    public var turnId: String?
    /// The delegated agent it belongs to. Absent means the session's own agent.
    public var agentId: String?
    /// The type and its fields.
    public var payload: AgentEventPayload

    /// The type on the wire.
    public var type: String { payload.type }

    /// Whether this build knows the type.
    public var isKnown: Bool {
        if case .unknown = payload { return false }
        return true
    }

    public init(
        v: String = JunoAgentProtocol.version,
        id: String,
        sessionId: String,
        seq: Int,
        at: String,
        turnId: String? = nil,
        agentId: String? = nil,
        payload: AgentEventPayload
    ) {
        self.v = v
        self.id = id
        self.sessionId = sessionId
        self.seq = seq
        self.at = at
        self.turnId = turnId
        self.agentId = agentId
        self.payload = payload
    }

    private enum EnvelopeKeys: String, CodingKey {
        case v = "v"
        case id = "id"
        case sessionId = "sessionId"
        case seq = "seq"
        case at = "at"
        case turnId = "turnId"
        case agentId = "agentId"
        case type = "type"
    }

    /// Tolerant in exactly the ways the TypeScript reader is: see the header of
    /// this file. Throws only when the object is not an envelope at all, or
    /// names a major version this build does not speak.
    public init(from decoder: any Decoder) throws {
        let raw = try AgentJSONValue(from: decoder)
        let container = try decoder.container(keyedBy: EnvelopeKeys.self)
        self.v = try container.decode(String.self, forKey: .v)
        guard JunoAgentProtocol.major(of: v) == JunoAgentProtocol.major else {
            throw DecodingError.dataCorruptedError(
                forKey: .v, in: container,
                debugDescription: "Agent protocol \(v) is not major \(JunoAgentProtocol.major)"
            )
        }
        self.id = try container.decode(String.self, forKey: .id)
        self.sessionId = try container.decode(String.self, forKey: .sessionId)
        self.seq = try container.decode(Int.self, forKey: .seq)
        self.at = try container.decode(String.self, forKey: .at)
        self.turnId = try? container.decodeIfPresent(String.self, forKey: .turnId)
        self.agentId = try? container.decodeIfPresent(String.self, forKey: .agentId)
        let type = try container.decode(String.self, forKey: .type)
        self.payload = AgentEventPayload(type: type, decoder: decoder) ?? .unknown(type: type, raw: raw)
    }

    public func encode(to encoder: any Encoder) throws {
        if case .unknown(_, let raw) = payload {
            try raw.encode(to: encoder)
            return
        }
        var container = encoder.container(keyedBy: EnvelopeKeys.self)
        try container.encode(v, forKey: .v)
        try container.encode(id, forKey: .id)
        try container.encode(sessionId, forKey: .sessionId)
        try container.encode(seq, forKey: .seq)
        try container.encode(at, forKey: .at)
        try container.encodeIfPresent(turnId, forKey: .turnId)
        try container.encodeIfPresent(agentId, forKey: .agentId)
        try container.encode(type, forKey: .type)
        try payload.encodeFields(to: encoder)
    }
}

/// What a command asks for, by type.
public enum AgentCommandPayload: Hashable, Sendable {
    /// Start a turn with a message. Refused while a turn runs; steer or queue instead.
    case turnSend(TurnSend)
    /// Give the running turn an instruction, taken before its next step.
    case turnSteer(TurnSteer)
    /// Hold a message until the running turn ends, then start a turn with it.
    case turnQueue(TurnQueue)
    /// Stop the running turn.
    case turnCancel(TurnCancel)
    /// Answer an approval request.
    case approvalDecide(ApprovalDecide)
    /// Answer a question.
    case questionAnswer(QuestionAnswer)
    /// Approve or reject a proposed plan.
    case planDecide(PlanDecide)
    /// Change what the next turn runs with. The host caps a remote sender at its own ceiling.
    case sessionSetMode(SessionSetMode)
    /// Set a goal. The reader sending it is the approval for the goal itself; it never changes the permission mode, and every action still asks as the mode says.
    case goalSet(GoalSet)
    /// Pause the active goal. The turn in flight finishes its current tool wave; no continuation starts.
    case goalPause(GoalPause)
    /// Resume a paused goal, or one that needs the reader.
    case goalResume(GoalResume)
    /// Change a goal. Only the fields that are set change; the next check uses them.
    case goalEdit(GoalEdit)
    /// Clear the goal. It stays readable as history.
    case goalClear(GoalClear)
    /// Carry a run on with no new message: retry a failed turn, or resume one the host lost. Refused while a turn runs.
    case runResume(RunResume)
    /// Grant another block of steps or budget to a run that stopped at a limit, and resume it.
    case runKeepGoing(RunKeepGoing)
