        case "turn.send":
            guard let value = try? TurnSend(from: decoder) else { return nil }
            self = .turnSend(value)
        case "turn.steer":
            guard let value = try? TurnSteer(from: decoder) else { return nil }
            self = .turnSteer(value)
        case "turn.queue":
            guard let value = try? TurnQueue(from: decoder) else { return nil }
            self = .turnQueue(value)
        case "turn.cancel":
            guard let value = try? TurnCancel(from: decoder) else { return nil }
            self = .turnCancel(value)
        case "approval.decide":
            guard let value = try? ApprovalDecide(from: decoder) else { return nil }
            self = .approvalDecide(value)
        case "question.answer":
            guard let value = try? QuestionAnswer(from: decoder) else { return nil }
            self = .questionAnswer(value)
        case "plan.decide":
            guard let value = try? PlanDecide(from: decoder) else { return nil }
            self = .planDecide(value)
        case "session.set_mode":
            guard let value = try? SessionSetMode(from: decoder) else { return nil }
            self = .sessionSetMode(value)
        case "goal.set":
            guard let value = try? GoalSet(from: decoder) else { return nil }
            self = .goalSet(value)
        case "goal.pause":
            guard let value = try? GoalPause(from: decoder) else { return nil }
            self = .goalPause(value)
        case "goal.resume":
            guard let value = try? GoalResume(from: decoder) else { return nil }
            self = .goalResume(value)
        case "goal.edit":
            guard let value = try? GoalEdit(from: decoder) else { return nil }
            self = .goalEdit(value)
        case "goal.clear":
            guard let value = try? GoalClear(from: decoder) else { return nil }
            self = .goalClear(value)
