    /// Start a turn with a message. Refused while a turn runs; steer or queue instead.
    public struct TurnSend: Hashable, Sendable, Codable {
        /// The message.
        public var text: String
        /// Uploaded attachments to include.
        public var attachmentIds: [String]?

        public init(
            text: String,
